select id, 1, 1, 'interval', '{"ms":{"title":"Interval 6 × 400m","objective":"Tingkatkan kelajuan dan kecekapan larian pada pace 5KM.","warmup":"Jalan laju 5 minit, kemudian 30 saat setiap satu: angkat lutut, tendang punggung, ayun kaki ke depan dan ke sisi. Tambah 10 minit lari santai.","main":"6 kali 400 meter pada pace yang kau boleh kekalkan untuk 5KM (usaha 7–8/10). Rehat 1:30 minit jog atau jalan di antara.","cooldown":"10 minit lari sangat santai, kemudian regangan.","coach":"Set pertama patut rasa terkawal. Kalau set terakhir jauh lebih perlahan, set awal kau terlalu laju."},"en":{"title":"Intervals 6 × 400m","objective":"Improve speed and running economy at 5KM pace.","warmup":"Brisk walk 5 minutes, then 30 seconds each: high knees, butt kicks, front and side leg swings. Add 10 minutes of easy running.","main":"6 × 400 m at the pace you could hold for a 5KM (effort 7–8/10). Rest 1:30 min jog or walk between.","cooldown":"10 minutes very easy running, then stretch.","coach":"The first rep should feel controlled. If your last rep is much slower, you started too fast."}}'::jsonb, 42, null, 'hard', 7, 8, '1:30 jog/walk', null
